import pyomo.environ as pyo

DATA = {
    "period_labels": ["6-10", "10-14", "14-18", "18-22", "22-2", "2-6"],
    "requirements": [60, 70, 60, 50, 20, 30],
    "shift_length_periods": 2,   # 8 continuous hours = 2 four-hour periods
    "n_periods": 6,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    n = d["n_periods"]
    shift_len = d["shift_length_periods"]
    periods = list(range(1, n + 1))

    m = pyo.ConcreteModel()
    m.T = pyo.Set(initialize=periods, ordered=True)

    m.requirement = pyo.Param(
        m.T, initialize={t: d["requirements"][t - 1] for t in periods}
    )

    # x[s]: number of crews starting at the beginning of period s
    m.x = pyo.Var(m.T, within=pyo.NonNegativeIntegers)

    # a[t,s]: 1 if a crew starting at s is on duty during period t (cyclic coverage)
    a = {}
    for t in periods:
        for s in periods:
            off = (t - s) % n
            a[(t, s)] = 1 if off <= shift_len - 1 else 0
    m.coverage = pyo.Param(m.T, m.T, initialize=a)

    def obj_rule(m):
        return sum(m.x[s] for s in m.T)

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def cover_rule(m, t):
        return sum(m.coverage[t, s] * m.x[s] for s in m.T) >= m.requirement[t]

    m.cover = pyo.Constraint(m.T, rule=cover_rule)

    return m
